    _check_imports(generated, sources)
    export_bindings = {
        "frozen_input_sha256": input_hash,
        "stage3_discovery_manifest_sha256": discovery_hash,
        "generated_tree_sha256": generated_hash,
        "trust_inventory_sha256": sidecar_hashes[
            "trust-inventory.json"
        ],
    }
    for field, expected_hash in export_bindings.items():
        if export_result.get(field) != expected_hash:
            label = (
                "trust inventory hash"
                if field == "trust_inventory_sha256"
                else field
            )
            raise KleanPreflightError(
                f"export result {label} does not match immutable inputs"
            )

    with tempfile.TemporaryDirectory(prefix="klean-preflight-") as temporary:
        clean = Path(temporary) / "project"
        shutil.copytree(generated, clean)
        diagnostics: list[dict[str, Any]] = []
        for command in (["lake", "clean"], ["lake", "build"]):
            code, output = run_command(command, cwd=clean, timeout=600)
            diagnostics.append(
                {
                    "command": command,
                    "exit_code": code,
                    "output_sha256": hashlib.sha256(output.encode()).hexdigest(),
                    "output_tail": output[-4000:],
                }
            )
            if code != 0:
                raise KleanPreflightError(
                    f"{' '.join(command)} failed ({code}): {output[-600:]}"
                )
    _require_unchanged_snapshot(
        snapshot, frozen_input, discovery_manifest, generation
    )
    return {
        "schema_version": 3,
        "status": "PASS" if obligations else "KLEAN_NO_OBLIGATIONS",
        "frozen_input_sha256": input_hash,
        "stage1_workspace_sha256": input_hash,
        "stage3_discovery_manifest_sha256": discovery_hash,
        "generated_tree_sha256": generated_hash,
        "target": target,
        "obligation_count": len(obligations),
        "trust_declaration_count": len(declared),
        "designated_sorry_count": 0,
        "diagnostics": diagnostics,
    }


def run_preflight(
    frozen_input: Path,
    discovery_manifest: Path,
    generation: Path,
    *,
    toolchain_lock: Path,
    run_command: Callable[..., tuple[int, str]] = _run,
) -> dict[str, Any]:
    frozen_input = Path(frozen_input)
    discovery_manifest = Path(discovery_manifest)
    generation = Path(generation)
    output = generation / "preflight.json"
    if output.exists() or output.is_symlink():
        raise KleanPreflightError(f"preflight result already exists: {output}")

    def error_document(error: KleanPreflightError) -> dict[str, Any]:
        try:
            stage1_hash = klean_export.tree_digest(frozen_input)
        except (OSError, klean_export.KleanExportError):
            stage1_hash = None
        try:
            stage3_hash = hashlib.sha256(
                discovery_manifest.read_bytes()
            ).hexdigest()
        except OSError:
            stage3_hash = None
        return {
            "schema_version": 3,
            "status": "KLEAN_PREFLIGHT_ERROR",
            "error": str(error),
            "stage1_workspace_sha256": stage1_hash,
            "stage3_discovery_manifest_sha256": stage3_hash,
        }

    publication_snapshot: PreflightSnapshot | None = None
    try:
        publication_snapshot = _preflight_snapshot(
            frozen_input, discovery_manifest, generation
        )
        document = check_generation(
            frozen_input,
            discovery_manifest,
            generation,
            toolchain_lock=toolchain_lock,
            run_command=run_command,
        )
        _require_unchanged_snapshot(
            publication_snapshot,
            frozen_input,
            discovery_manifest,
            generation,
        )
    except KleanPreflightError as error:
        document = error_document(error)
    temporary = output.with_name(f".{output.name}.tmp")
    temporary.write_text(json.dumps(document, indent=2, sort_keys=True) + "\n")
    if (
        document.get("status") in {"PASS", "KLEAN_NO_OBLIGATIONS"}
        and publication_snapshot is not None
    ):
        try:
            _require_unchanged_snapshot(
                publication_snapshot,
                frozen_input,
                discovery_manifest,
                generation,
            )
        except KleanPreflightError as error:
            document = error_document(error)
            temporary.write_text(
                json.dumps(document, indent=2, sort_keys=True) + "\n"
            )
    os.replace(temporary, output)
    return document


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--input", required=True, type=Path)
    parser.add_argument("--discovery-manifest", required=True, type=Path)
    parser.add_argument("--generation", required=True, type=Path)
    parser.add_argument(
        "--toolchain-lock",
        type=Path,
        default=REPO / "data/klean-toolchain.lock.json",
    )
    arguments = parser.parse_args(argv)
    try:
        result = run_preflight(
            arguments.input,
            arguments.discovery_manifest,
            arguments.generation,
            toolchain_lock=arguments.toolchain_lock,
        )
    except KleanPreflightError as error:
        print(f"Klean preflight failed: {error}", file=sys.stderr)
        return 2
    print(json.dumps(result, sort_keys=True))
    return (
        0
        if result["status"] in {"PASS", "KLEAN_NO_OBLIGATIONS"}
        else 1
    )


if __name__ == "__main__":
    raise SystemExit(main())
#!/usr/bin/env python3
"""Deterministically export one frozen K proof workspace to a Lean project."""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import shutil
import shlex
import stat
import subprocess
import sys
import tempfile
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable


REPO = Path(__file__).resolve().parent.parent
KLEAN = REPO / "tools/klean.py"
KOMPILE_TIMEOUT = 480
KLEAN_TIMEOUT = 300
BUILD_TIMEOUT = 600

K_IDENTIFIER = r"[A-Za-z][A-Za-z0-9_'-]*"
SYNTAX_BLOCK_RE = re.compile(
    rf"(?ms)^[ \t]*syntax\s+(?P<ret>{K_IDENTIFIER})\s*::=\s*"
    r"(?P<body>.*?)"
    r"(?=^[ \t]*(?:syntax|rule|module|endmodule|imports)\b|\Z)"
)
FUNC_PRODUCTION_RE = re.compile(
    r"(?:\A|^[ \t]*\|)\s*"
    rf"(?P<name>{K_IDENTIFIER})\s*\((?P<args>[^)]*)\)\s*"
    r"\[(?P<attrs>[^\]]*)\]",
    re.M,
)
K_IDENTIFIER_END = r"(?![A-Za-z0-9_'-])"
MODULE_RE = re.compile(
    rf"(?m)^[ \t]*module\s+({K_IDENTIFIER}){K_IDENTIFIER_END}"
)
MODULE_BLOCK_RE = re.compile(
    rf"(?ms)^[ \t]*module\s+(?P<name>{K_IDENTIFIER}){K_IDENTIFIER_END}"
    r"(?P<body>.*?)\bendmodule\b"
)
IMPORT_RE = re.compile(
    rf"(?m)^[ \t]*imports\s+({K_IDENTIFIER}){K_IDENTIFIER_END}"
)
REQUIRES_RE = re.compile(r'requires\s+"([^"]+)"')
_TERM_HEAD_RE = re.compile(r"fail to show termination for\s*\n\s*(«[^»]+»|\S+)")
_TERM_CALL_RE = re.compile(r"Call from («[^»]+»|\S+) to («[^»]+»|\S+)")
_ELAB_LINE_RE = re.compile(
    r"error:\s+\S*Func\.lean:(\d+):\d+:\s+"
    r"(?:unknown identifier|Application type mismatch)"
)
_DEF_RE = re.compile(r"^(\s*)(?:noncomputable\s+)?def\s+(\S+)\b")
_NONCOMPUTABLE_RE = re.compile(r"(?m)^\s*noncomputable\s+def\s+(\S+)")
_LEAN_NAMESPACE_RE = re.compile(r"^\s*namespace\s+(\S+)\s*$")
_LEAN_END_RE = re.compile(r"^\s*end(?:\s+(\S+))?\s*$")
_LEAN_TRUST_DECL_RE = re.compile(
    r"^\s*(axiom|opaque)\s+(\S+)\s+(.+?)\s*$"
)
_RULE_HEAD_RE = re.compile(
    rf"(?m)^\s*rule(?:\s+\[[^\]]+\]:)?\s+"
    rf"(?P<name>{K_IDENTIFIER}){K_IDENTIFIER_END}"
)
_SYNTAX_PRODUCTION_LINE_RE = re.compile(
    rf"^(?P<prefix>[ \t]*(?:syntax\s+{K_IDENTIFIER}\s*::=\s*|\|\s*))"
    rf"(?P<name>{K_IDENTIFIER})\s*\((?P<args>[^)]*)\)"
    r"(?P<spacing>[ \t]*)(?P<attrs>\[[^\]]*\])?"
    r"(?P<suffix>[ \t]*(?://.*)?)$"
)

if str(REPO) not in sys.path:
    sys.path.insert(0, str(REPO))

from tools import k_rule_inventory, lemma_discovery_contract


class KleanExportError(RuntimeError):
    pass


@dataclass(frozen=True)
class Func:
    name: str
    ret: str
    args: list[str]


@dataclass(frozen=True)
class DefinitionResolution:
    verification_file: Path
    verification_module: str
    syntax_module: str
    required_files: tuple[Path, ...]
    entry_files: tuple[Path, ...]


@dataclass(frozen=True)
class KompileCommand:
    source: Path
    main_module: str | None
    syntax_module: str | None
    backend: str | None


def _proof_kompile_commands(workspace: Path) -> tuple[KompileCommand, ...]:
    prove = workspace / "prove.sh"
    if not prove.is_file() or prove.is_symlink():
        return ()
    logical_lines = prove.read_text().replace("\\\n", " ").splitlines()
    commands: list[KompileCommand] = []
    for line in logical_lines:
        try:
            words = shlex.split(line, comments=True)
        except ValueError:
            continue
        try:
            index = words.index("kompile")
        except ValueError:
            continue
        arguments = words[index + 1 :]
        source_word = next(
            (
                word
                for word in arguments
                if not word.startswith("-") and word.endswith(".k")
            ),
            None,
        )
        if source_word is None:
            continue
        source = (workspace / source_word).resolve()
        try:
            source.relative_to(workspace)
        except ValueError:
            continue
        if not source.is_file() or source.is_symlink():
            continue

        def option(name: str) -> str | None:
            if name not in arguments:
                return None
            option_index = arguments.index(name)
            if option_index + 1 >= len(arguments):
                return None
            return arguments[option_index + 1]

        commands.append(
            KompileCommand(
                source=source,
                main_module=option("--main-module"),
                syntax_module=option("--syntax-module"),
                backend=option("--backend"),
            )
        )
    return tuple(commands)


def _workspace_k_files(workspace: Path) -> tuple[Path, ...]:
    workspace = Path(workspace)
    if not workspace.is_dir() or workspace.is_symlink():
        raise KleanExportError("K definition workspace must be a real directory")
    files = tuple(
        path.resolve()
        for _relative, kind, path in _tree_entries(workspace)
        if kind == "file" and path.suffix == ".k"
    )
    if not files:
        raise KleanExportError("K definition workspace contains no .k files")
    return tuple(sorted(files, key=str))


def _local_required_file(source: Path, required: str, workspace: Path) -> Path | None:
    candidate = Path(required)
    unresolved = (
        candidate
        if candidate.is_absolute()
        else source.parent / candidate
    )
    resolved = unresolved.resolve()
    try:
        resolved.relative_to(workspace)
    except ValueError:
        raise KleanExportError(
            "K definition requires a file outside the frozen workspace: "
            f"{required}"
        )
    if not resolved.exists():
        if resolved.suffix == ".k":
            raise KleanExportError(
                f"K definition requires a missing workspace .k file: {required}"
            )
        return None
    if unresolved.is_symlink() or not resolved.is_file() or resolved.suffix != ".k":
        raise KleanExportError(
            f"K definition require is not a regular workspace .k file: {resolved}"
        )
    return resolved


def resolve_definition_closure(workspace: Path) -> DefinitionResolution:
    original_workspace = Path(workspace)
    try:
        workspace_mode = original_workspace.stat(
            follow_symlinks=False
        ).st_mode
    except OSError as error:
        raise KleanExportError(
            "K definition workspace must be a real directory"
        ) from error
    if not stat.S_ISDIR(workspace_mode):
        raise KleanExportError(
            "K definition workspace must be a real directory"
        )
    workspace = original_workspace.resolve()
    verification_file = workspace / "verification.k"
    if not verification_file.is_file() or verification_file.is_symlink():
        raise KleanExportError(
            "K definition workspace is missing regular verification.k"
        )
    files = _workspace_k_files(workspace)
    # A prove.sh may leave mutation and bridge byproducts (verification-mutant.k,
    # spec-mutant.k, spec-body-mutation.k, ...) in the workspace that reuse the
    # canonical module names SPEC/VERIFICATION.  Record every declaration during
    # the flat scan without failing on a collision; ambiguity is adjudicated
    # below against the files actually reached from the export target, so an
    # unreached duplicate is ignored while a reached duplicate still fails
    # closed.
    module_declarations: dict[str, list[tuple[Path, tuple[str, ...]]]] = {}
    file_modules: dict[Path, tuple[str, ...]] = {}
    file_requires: dict[Path, tuple[Path, ...]] = {}
    for path in files:
        text = path.read_text()
        declared: list[str] = []
        for block in MODULE_BLOCK_RE.finditer(text):
            name = block.group("name")
            imports = tuple(IMPORT_RE.findall(block.group("body")))
            module_declarations.setdefault(name, []).append((path, imports))
            declared.append(name)
        file_modules[path] = tuple(declared)
        file_requires[path] = tuple(
            required_path
            for required in REQUIRES_RE.findall(text)
            if (
                required_path := _local_required_file(
                    path, required, workspace
                )
            )
            is not None
        )

    try:
        verification_module = k_rule_inventory.inventory_verification(
            workspace
        )["verification_module"]
    except k_rule_inventory.KRuleInventoryError as error:
        raise KleanExportError(str(error)) from error
    if verification_module not in file_modules.get(verification_file, ()):
        raise KleanExportError(
            "selected verification module is not defined in verification.k"
        )

    def _requires_reaches(source: Path, target: Path) -> bool:
        """True when ``target`` lies in ``source``'s transitive requires."""

        seen: set[Path] = set()
        stack = [source]
        while stack:
            current = stack.pop()
            if current in seen:
                continue
            seen.add(current)
            if current == target:
                return True
            stack.extend(file_requires.get(current, ()))
        return False

    commands = _proof_kompile_commands(workspace)
    # A kompile command seeds the export closure only when its source is the
    # frozen verification target or transitively requires it.  This keeps a
    # legitimate reverse-require compilation root (a driver that requires
    # verification.k) reachable while excluding mutation and bridge byproducts
    # (verification-mutant.k re-declares VERIFICATION beside the target,
    # bridge-verification.k compiles a parallel definition) that would otherwise
    # pollute the closure with duplicate targets.
    export_commands = tuple(
        command
        for command in commands
        if _requires_reaches(command.source, verification_file)
    )

    def _resolve_module_file(
        name: str,
    ) -> tuple[Path, tuple[str, ...]] | None:
        """Bind ``name`` to the reached file declaring it, failing closed on a
        genuine ambiguity among candidate files."""

        candidates = module_declarations.get(name)
        if not candidates:
            return None
        reached = [
            (path, imports)
            for path, imports in candidates
            if path in reached_files
        ]
        if reached:
            distinct = {path for path, _ in reached}
            if len(distinct) > 1:
                raise KleanExportError(
                    f"duplicate module definition {name}: "
                    + " and ".join(str(path) for path in sorted(distinct, key=str))
                )
            return reached[0]
        if len(candidates) == 1:
            return candidates[0]
        raise KleanExportError(
            f"duplicate module definition {name}: "
            + " and ".join(
                str(path)
                for path in sorted({path for path, _ in candidates}, key=str)
            )
        )

    reached_modules: set[str] = set()
    reached_files: set[Path] = set()
    pending_modules = [verification_module]
    pending_files = [
        verification_file,
        *(command.source for command in export_commands),
    ]
    pending_modules.extend(
        module
        for command in export_commands
        for module in (command.main_module, command.syntax_module)
        if module is not None and module in module_declarations
    )
    while pending_modules or pending_files:
        while pending_files:
            path = pending_files.pop()
            if path in reached_files:
                continue
            reached_files.add(path)
            pending_files.extend(file_requires.get(path, ()))
        if not pending_modules:
            continue
        name = pending_modules.pop()
        if name in reached_modules:
            continue
        reached_modules.add(name)
        resolved = _resolve_module_file(name)
        if resolved is None:
            continue
        path, imports = resolved
        if path not in reached_files:
            pending_files.append(path)
        pending_modules.extend(imports)

    try:
        text = script.read_text()
    except (OSError, UnicodeError) as error:
        raise KRuleInventoryError(f"cannot read prove.sh: {script}") from error
    logical = re.sub(r"\\\r?\n", " ", text)
    selected: str | None = None
    for line in logical.splitlines():
        code = line.split("#", 1)[0]
        if not re.search(r"(?:^|[;&|]\s*)kompile\s+", code):
            continue
        if re.search(r"(?:^|\s)(?:\./)?verification\.k(?:\s|$)", code) is None:
            continue
        match = re.search(
            r"(?:^|\s)--main-module(?:=|\s+)([A-Za-z][A-Za-z0-9_'-]*)",
            code,
        )
        if match is not None:
            selected = match.group(1)
    return selected


def _verification_closure(
    modules: tuple[_Module, ...], verification: _Module
) -> tuple[_Module, ...]:
    by_name = {module.name: module for module in modules}
    reached: set[str] = set()
    pending = [verification.name]
    while pending:
        name = pending.pop()
        if name in reached:
            continue
        reached.add(name)
        module = by_name.get(name)
        if module is not None:
            pending.extend(module.imports)
    return tuple(module for module in modules if module.name in reached)


def _without_comments(text: str) -> str:
    """Remove K comments while preserving strings and their exact contents."""

    output: list[str] = []
    index = 0
    block_depth = 0
    state = "code"
    while index < len(text):
        character = text[index]
        following = text[index + 1] if index + 1 < len(text) else ""
        if state == "line-comment":
            if character in "\r\n":
                output.append(character)
                state = "code"
            index += 1
            continue
        if state == "string":
            output.append(character)
            if character == "\\" and following:
                output.append(following)
                index += 2
                continue
            if character == '"':
                state = "code"
            index += 1
            continue
        if state == "block-comment":
            if character == "/" and following == "*":
                block_depth += 1
                index += 2
                continue
            if character == "*" and following == "/":
                block_depth -= 1
                index += 2
                if block_depth == 0:
                    state = "code"
                continue
            if character in "\r\n":
                output.append(character)
            index += 1
            continue
        if character == "/" and following == "/":
            output.append(" ")
            state = "line-comment"
            index += 2
            continue
        if character == "/" and following == "*":
            output.append(" ")
            state = "block-comment"
            block_depth = 1
            index += 2
            continue
        output.append(character)
        if character == '"':
            state = "string"
        index += 1
    return "".join(output)


def _attribute_tokens(text: str, masked_text: str) -> list[str]:
    tokens: list[str] = []
    start = 0
    depth = 0
    for index, character in enumerate(masked_text):
        if character in "([{":
            depth += 1
        elif character in ")]}":
            depth = max(depth - 1, 0)
        elif character == "," and depth == 0:
            token = _without_comments(text[start:index]).strip()
            if token:
                tokens.append(token)
            start = index + 1
    final = _without_comments(text[start:]).strip()
    if final:
        tokens.append(final)
    return tokens


def _rule_spans(text: str, module: _Module) -> list[_RuleSpan]:
    masked_text = _mask_non_code(text)
    sentences = module.sentences
    rules: list[_RuleSpan] = []
    seen_hashes: set[str] = set()
    for index, sentence in enumerate(sentences):
        if sentence.keyword != "rule":
            continue
        end_offset = (
            sentences[index + 1].start
            if index + 1 < len(sentences)
            else module.content_end
        )
        start_offset = sentence.start
        raw_segment = text[start_offset:end_offset]
        masked_segment = masked_text[start_offset:end_offset]
        logical_length = len(masked_segment.rstrip(" \t\r\n"))
        if logical_length == 0:
            continue
        rule_text = raw_segment[:logical_length].rstrip(" \t\r\n")
        masked_rule = _mask_non_code(rule_text)
        attribute_match = _TRAILING_ATTRIBUTES_RE.search(masked_rule)
        attribute_start = None
        attribute_end = None
        attributes: list[str] = []
        if attribute_match is not None:
            attribute_start = attribute_match.start("attributes")
            attribute_end = attribute_match.end("attributes")
            attributes = _attribute_tokens(
                rule_text[attribute_start:attribute_end],
                masked_rule[attribute_start:attribute_end],
            )
        normalized = " ".join(rule_text.split())
        digest = hashlib.sha256(normalized.encode()).hexdigest()
        if digest in seen_hashes:
            raise KRuleInventoryError(
                f"duplicate normalized simplification rule hash: {digest}"
            )
        seen_hashes.add(digest)
        start_line = text.count("\n", 0, start_offset) + 1
        end_line = start_line + rule_text.count("\n")
        rule = KRule(
            source_rule_id=f"rule-{digest}",
            module=module.name,
            start_line=start_line,
            end_line=end_line,
            normalized_sha256=digest,
            attributes=attributes,
            text=rule_text,
        )
        rules.append(
            _RuleSpan(
                rule=rule,
                start_offset=start_offset,
                end_offset=start_offset + len(rule_text),
                attribute_start=(
                    None
                    if attribute_match is None
                    else start_offset + attribute_match.start()
                ),
                attribute_end=(
                    None
                    if attribute_match is None
                    else start_offset + attribute_match.end()
                ),
            )
        )
    return rules


def _rule_documents(
    text: str, modules: tuple[_Module, ...]
) -> list[dict[str, Any]]:
    spans = [span for module in modules for span in _rule_spans(text, module)]
    spans.sort(key=lambda span: span.start_offset)
    return [dataclasses.asdict(span.rule) for span in spans]


def _attribute_token_spans(
    text: str,
    masked_text: str,
) -> list[tuple[int, int, str]]:
    spans: list[tuple[int, int, str]] = []
    start = 0
    depth = 0
    for index, character in enumerate(masked_text):
        if character in "([{":
            depth += 1
        elif character in ")]}":
            depth = max(depth - 1, 0)
        elif character == "," and depth == 0:
            spans.append(
                (
                    start,
                    index,
                    _without_comments(text[start:index]).strip(),
                )
            )
            start = index + 1
    spans.append(
        (
            start,
            len(text),
            _without_comments(text[start:]).strip(),
        )
    )
    return spans


def _blank_non_newlines(text: str) -> str:
    return "".join(
        character if character in "\r\n" else " "
        for character in text
    )


def desimplify_rule_ids(
    text: str,
    source_rule_ids: list[str],
) -> str:
    """Remove simplification from exactly the selected canonical rule IDs."""

    if len(source_rule_ids) != len(set(source_rule_ids)):
        raise KRuleInventoryError(
            "exact rule transformation contains a duplicate source rule ID"
        )
    selected = set(source_rule_ids)
    modules = _modules(_mask_non_code(text))
    spans = [
        span
        for local_module in modules
        for span in _rule_spans(text, local_module)
    ]
